xql_query:
dataset = proofpoint_tap_raw
| filter _log_type = "message-blocked" and threatsInfoMap contains "MALWARE"
// recipient is a JSON array held as text, so one blocked message carried every
// targeted user in a single alert. Expand to one alert per recipient, keeping the
// full list in all_recipients for triage.
| alter all_recipients = recipient
| alter recipient_expanded = json_extract_array(recipient, "$")
| arrayexpand recipient_expanded
| alter recipient = json_extract_scalar(recipient_expanded, "$")
// fromAddress is a single-element JSON array; unwrap it so the alert carries a
// bare address rather than ["addr"].
| alter fromAddress = json_extract_scalar(fromAddress, "$[0]")
// campaignId is top-level on click events but nested inside
// threatsInfoMap on message events; take whichever exists.
| alter campaignId = coalesce(campaignId, json_extract_scalar(threatsInfoMap, "$[0].campaignId"))
